draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // lion body
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2 * Math.PI);
  ctx.stroke();

  // lion mane
  ctx.beginPath();
  ctx.moveTo(W/2 + 30, H/2 - 20);
  ctx.lineTo(W/2 + 50, H/2);
  ctx.lineTo(W/2 + 30, H/2 + 20);
  ctx.stroke();

  // lion face
  ctx.beginPath();
  ctx.arc(W/2, H/2 - 30, 20, 0, 2 * Math.PI);
  ctx.stroke();

  // lion mouth
  ctx.beginPath();
  ctx.moveTo(W/2 - 10, H/2 - 20);
  ctx.lineTo(W/2 + 10, H/2 - 20);
  ctx.stroke();

  // lion roar
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 40);
  ctx.lineTo(W/2 + Math.sin(t) * 50, H/2 - 60 + Math.cos(t) * 20);
  ctx.stroke();

  ctx.restore();
}
